challenge_result.network_analysis:
{
  "summary": "The primary fault originates at rtpengine, which is exhibiting a 100ms network latency that stalls call setups; this explicitly demotes UPF, P-CSCF, I-CSCF, and S-CSCF as secondary reporters, since the latency causes the media collapse at UPF and inflates the system-wide signaling retries across the CSCFs.",
  "layer_status": {},
  "hypotheses": [
    {
      "id": "h1",
      "statement": "rtpengine is the source of the collapsed UPF activity during calls and the system-wide IMS signaling spikes.",
      "primary_suspect_nf": "rtpengine",
      "supporting_events": [
        "core.upf.activity_during_calls_collapsed"
      ],
      "explanatory_fit": 0.95,
      "falsification_probes": [
        "Check tc -s qdisc show dev eth0 on rtpengine to detect kernel-level network latency or drops, as L04 notes internal errors_per_second is blind to this.",
        "Review measure_rtt results from P-CSCF to RTPEngine to confirm the 100ms path latency."
      ],
      "specificity": "specific"
    },
    {
      "id": "h2",
      "statement": "upf is the source of the collapsed activity during calls, aligning with the vonr_media_stops branch of the n3_data_plane_outage chain.",
      "primary_suspect_nf": "upf",
      "supporting_events": [
        "core.upf.activity_during_calls_collapsed"
      ],
      "explanatory_fit": 0.3,
      "falsification_probes": [
        "Check UPF application logs for data plane processing errors or internal packet drops.",
        "Verify with measure_rtt if the UPF to RTPEngine path is the exclusive source of the fault rather than RTPEngine itself."
      ],
      "specificity": "moderate"
    },
    {
      "id": "h3",
      "statement": "pcscf is the source of the elevated active dialogs and signaling rates.",
      "primary_suspect_nf": "pcscf",
      "supporting_events": [],
      "explanatory_fit": 0.15,
      "falsification_probes": [
        "Check P-CSCF application metrics and logs for internal stalls or processing errors during call setup.",
        "Run measure_rtt from UE to P-CSCF to confirm signaling path latency."
      ],
      "specificity": "moderate"
    }
  ]
}

challenge_result.investigation_instruction:
{
  "plans": [
    {
      "hypothesis_id": "h1",
      "hypothesis_statement": "rtpengine is the source of the collapsed UPF activity during calls and the system-wide IMS signaling spikes.",
      "primary_suspect_nf": "rtpengine",
      "probes": [
        {
          "tool": "measure_rtt",
          "args_hint": "measure_rtt('pcscf', rtpengine_ip)",
          "expected_if_hypothesis_holds": "High round-trip time (e.g., ~100ms) or packet loss is observed on the path to rtpengine.",
          "falsifying_observation": "The probe's reading is inconsistent with rtpengine being the source (e.g., latency is low and no packet loss is observed).",
          "conflates_with": [
            "pcscf network interface",
            "network path between pcscf and rtpengine"
          ]
        },
        {
          "tool": "measure_rtt",
          "args_hint": "measure_rtt('pcscf', upf_ip)",
          "expected_if_hypothesis_holds": "Latency is low (< 5ms) on this path, isolating the latency observed in the first probe to rtpengine rather than the pcscf network interface.",
          "falsifying_observation": "High latency is observed on this path as well, meaning the original reading was attributable to the pcscf network interface, not rtpengine.",
          "conflates_with": []
        },
        {
          "tool": "get_dp_quality_gauges",
          "args_hint": "window_seconds=120 to read rtpengine.errors_per_second and rtpengine.loss_ratio",
          "expected_if_hypothesis_holds": "Probe reads `rtpengine.errors_per_second` with a spike > 0, or `rtpengine.loss_ratio` > 0.",
          "falsifying_observation": "The probe's reading is inconsistent with rtpengine being the source (e.g., the metrics stay at their healthy baseline of zero).",
          "conflates_with": []
        }
      ],
      "notes": "Testing the specific 100ms network latency identified by the NA. measure_rtt targets rtpengine from pcscf, with a partner probe to upf to isolate the delay. get_dp_quality_gauges checks the KB-authored verification path for rtpengine drops."
    },
    {
      "hypothesis_id": "h2",
      "hypothesis_statement": "upf is the source of the collapsed activity during calls, aligning with the vonr_media_stops branch of the n3_data_plane_outage chain.",
      "primary_suspect_nf": "upf",
      "probes": [
        {
          "tool": "measure_rtt",
          "args_hint": "measure_rtt('rtpengine', upf_ip)",
          "expected_if_hypothesis_holds": "High round-trip time or packet loss is observed on the path to upf.",
          "falsifying_observation": "The probe's reading is inconsistent with upf being the source (e.g., latency is low and no packet loss is observed).",
          "conflates_with": [
            "rtpengine network interface",
            "network path between rtpengine and upf"
          ]
        },
        {
          "tool": "measure_rtt",
          "args_hint": "measure_rtt('rtpengine', pcscf_ip)",
          "expected_if_hypothesis_holds": "Latency is low (< 5ms) on this path, isolating the latency observed in the first probe to upf rather than the rtpengine network interface.",
          "falsifying_observation": "High latency is observed on this path as well, meaning the original reading was attributable to the rtpengine network interface, not upf.",
          "conflates_with": []
        },
        {
          "tool": "get_dp_quality_gauges",
          "args_hint": "window_seconds=120 to check upf.gtp_indatapktn3upf_per_ue and upf.gtp_outdatapktn3upf_per_ue",
          "expected_if_hypothesis_holds": "Probe reads a drop in `upf.gtp_indatapktn3upf_per_ue` or `upf.gtp_outdatapktn3upf_per_ue` indicating a collapsed data plane.",
          "falsifying_observation": "The probe reads values within the typical healthy range, staying at their baseline.",
          "conflates_with": []
        }
      ],
      "notes": "Aligns with the n3_data_plane_outage chain. Uses partner measure_rtt probes to disambiguate upf-path latency from rtpengine constraints."
    },
    {
      "hypothesis_id": "h3",
      "hypothesis_statement": "pcscf is the source of the elevated active dialogs and signaling rates.",
      "primary_suspect_nf": "pcscf",
      "probes": [
        {
          "tool": "measure_rtt",
          "args_hint": "measure_rtt('pcscf', icscf_ip)",
          "expected_if_hypothesis_holds": "High latency or packet loss is observed on the path to icscf.",
          "falsifying_observation": "The probe's reading is inconsistent with pcscf being the source (e.g., latency is low and no packet loss is observed).",
          "conflates_with": [
            "pcscf network interface",
            "network path between pcscf and icscf"
          ]
        },
        {
          "tool": "measure_rtt",
          "args_hint": "measure_rtt('pcscf', upf_ip)",
          "expected_if_hypothesis_holds": "Latency is low (< 5ms) on this path, isolating the latency observed in the first probe to the path toward icscf rather than the pcscf network interface.",
          "falsifying_observation": "High latency is observed on this path as well, meaning the original reading was attributable to the pcscf network interface.",
          "conflates_with": []
        },
        {
          "tool": "run_kamcmd",
          "args_hint": "run_kamcmd('pcscf', 'stats.fetch script:register_time')",
          "expected_if_hypothesis_holds": "Probe reads `pcscf.avg_register_time_ms` and finds a value significantly elevated above the healthy range or zero (stall signature).",
          "falsifying_observation": "The probe reads a value within the typical healthy range (e.g., 150-350ms), inconsistent with pcscf stalling signaling.",
          "conflates_with": []
        }
      ],
      "notes": "Checks P-CSCF latency and stall states as indicated by the NA. Uses partner measure_rtt probes to cleanly attribute path delays."
    }
  ]
}
